function getRepoDetails(actionDetails) {
    let owner = "";
    let repo = "";

    if ("recommendations" in actionDetails) {
        if ("meta_data" in actionDetails["recommendations"]) {
            let metadata = actionDetails["recommendations"]["meta_data"];
            owner = "org_name" in metadata ? metadata["org_name"] : null;
            repo = "repo_name" in metadata ? metadata["repo_name"] : null;

            return {
                owner,
                repo
            };
        }
    }

    return {
        owner,
        repo
    };
};

function getPullRequestNumber(actionDetails) {
    let pr_url, pr_number;

    if ("pull_request" in actionDetails) {
        pr_url = "url" in actionDetails["pull_request"] ? actionDetails["pull_request"]["url"] : null;
    }

    if (pr_url) {
        const match = pr_url.match(/\/pull\/(\d+)(?:\/|$|\?)/);
        pr_number = match ? Number(match[1]) : null;

        if (pr_number) {
            return pr_number;
        }
    }
}

