function getPRStatus(prDetails) {
    const state = prDetails["state"];
    const merged = prDetails["merged"];

    if (state == "open") {
        return "open";
    } else if (merged) {
        return "merged";
    } else {
        return "closed";
    }
};

function getActionStatus(status) {
    if (status == "merged") {
        return "success";
    } else {
        return "rejected";
    }
}

